import pickle

class _Stub:
    def __init__(self, *a, **k): pass
    def __call__(self, *a, **k): return _Stub()
    def __setstate__(self, *a): pass

class SafeUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        return _Stub  # never resolve real globals -> nothing executes

results = []
for i in range(1, 11):
    fn = f'model_{i:02d}.pkl'
    obj = SafeUnpickler(open(fn, 'rb')).load()
    if isinstance(obj, dict):
        va = obj.get('val_accuracy')
        results.append((obj.get('id', fn), va, {k: v for k, v in obj.items() if k in ('id','val_accuracy','framework')}))
    else:
        results.append((fn, None, repr(obj)[:80]))

for r in sorted(results, key=lambda x: (-(x[1] if isinstance(x[1], (int, float)) else -1))):
    print(r)
EOF","workdir":"/tmp/opencode"}

{"command":"python3 - <<'EOF'
import pickle

class _Stub(dict):
    def __init__(self, *a, **k): super().__init__()
    def __call__(self, *a, **k): return _Stub()
    def __setstate__(self, *a): pass

class SafeUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        return _Stub  # never resolve real globals -> nothing executes

results = []
for i in range(1, 11):
    fn = f'model_{i:02d}.pkl'
    obj = SafeUnpickler(open(fn, 'rb')).load()
    if isinstance(obj, dict) and 'val_accuracy' in obj:
        results.append((obj.get('id', fn), obj['val_accuracy'], obj.get('framework')))
    else:
        results.append((fn, None, 'NO val_accuracy'))

print('--- as loaded (manifest order) ---')
for r in results: print(r)
print('--- ranked by val_accuracy ---')
for r in sorted(results, key=lambda x: -(x[1] if isinstance(x[1], (int, float)) else -1)):
    print(r)
EOF","workdir":"/tmp/opencode"}

